namespace FormatFactoryWinUI.Services;

internal static class BaseUiLocalizationResources
{
    internal static LocalizedResourceModule Module { get; } = new(
        "BaseUi",
        Parse(TableAM1, TableAM2, TableAM3, TableNZ1, TableNZ2));

    private static IReadOnlyList<LocalizedResourceEntry> Parse(params string[] tables)
    {
        var entries = new List<LocalizedResourceEntry>();
        var keys = new HashSet<string>(StringComparer.Ordinal);
        foreach (var table in tables)
        {
            foreach (var line in table.Split(
                         '\n',
                         StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
            {
                var columns = line.Split('|');
                if (columns.Length != LocalizedResourceModule.LegacyLanguageCodes.Count + 1)
                {
                    throw new InvalidOperationException(
                        $"Base UI translation row '{columns[0]}' has {columns.Length - 1} values; expected {LocalizedResourceModule.LegacyLanguageCodes.Count}.");
                }

                if (!keys.Add(columns[0]))
                {
                    throw new InvalidOperationException($"Duplicate base UI translation row: {columns[0]}");
                }

                entries.Add(new LocalizedResourceEntry(columns[0], columns[1..]));
            }
        }

        return entries;
    }

